async function cleanup() {
  if (cleaned) return;
  cleaned = true;
  if(testStripe){
    for(const id of testSessions)try{const session=await testStripe.checkout.sessions.retrieve(id);if(session.livemode)throw Error('Refusing live session');if(session.status==='open')await testStripe.checkout.sessions.expire(id);const intent=typeof session.payment_intent==='string'?session.payment_intent:session.payment_intent?.id;if(intent)testIntents.add(intent)}catch(error){console.error('Test session cleanup failed:',error.message);process.exitCode=1;}
    for(const id of testIntents)try{const payment=await testStripe.paymentIntents.retrieve(id);if(payment.livemode)throw Error('Refusing live payment');const refunds=await testStripe.refunds.list({payment_intent:id,limit:100});const returned=refunds.data.filter(r=>r.status==='succeeded'||r.status==='pending').reduce((sum,r)=>sum+r.amount,0);const left=payment.amount_received-returned;if(left>0)await testStripe.refunds.create({payment_intent:id,amount:left,metadata:{fixture:'synthetic_cross_stock_cleanup'}},{idempotencyKey:`synthetic-cross-cleanup-${id}`});let complete=false;for(let i=0;i<20;i++){const current=await testStripe.refunds.list({payment_intent:id,limit:100});if(current.data.filter(r=>r.status==='succeeded').reduce((sum,r)=>sum+r.amount,0)===payment.amount_received){complete=true;break}await sleep(1000)}if(!complete)throw Error('Test refund has not reached succeeded status');}catch(error){console.error('Test payment cleanup failed:',error.message);process.exitCode=1;}
  }
  if (syncProxy) await new Promise(resolve => syncProxy.close(resolve));
  if (syntheticProvider) await new Promise(resolve => syntheticProvider.close(resolve));
  for (const child of children) if (child.pid) { try { process.kill(-child.pid, 'SIGTERM'); } catch (error) { if (error.code !== 'ESRCH') throw error; } }
  for (let attempt = 0; attempt < 50 && children.some(child => child.exitCode === null && child.signalCode === null); attempt++) await sleep(100);
  for (const child of children) if (child.pid && child.exitCode === null && child.signalCode === null) { try { process.kill(-child.pid, 'SIGKILL'); } catch (error) { if (error.code !== 'ESRCH') throw error; } }
  fs.rmSync(workspace, { recursive: true, force: true });
}
for (const [signal, code] of [['SIGINT', 130], ['SIGTERM', 143]]) process.once(signal, () => { cleanup().finally(() => process.exit(code)); });

async function launch(name, source, fixture) {
  const dir = path.join(workspace, name);
  fs.mkdirSync(dir);
  for (const entry of ['convex', 'src', 'shared']) if (fs.existsSync(path.join(source, entry))) fs.cpSync(path.join(source, entry), path.join(dir, entry), { recursive: true });
  for (const entry of ['package.json', 'tsconfig.json', 'convex.json']) if (fs.existsSync(path.join(source, entry))) fs.copyFileSync(path.join(source, entry), path.join(dir, entry));
  fs.symlinkSync(path.join(source, 'node_modules'), path.join(dir, 'node_modules'), 'dir');
  fs.copyFileSync(path.join(__dirname, 'fixtures', fixture), path.join(dir, 'convex', 'cross_stock_fixture.ts'));
  if (name === 'website') {
    fs.copyFileSync(path.join(__dirname, 'fixtures', 'cross-stock-bridge.ts.fixture'), path.join(dir, 'convex', 'sharedStockBridge.ts'));
    fs.copyFileSync(path.join(__dirname, 'fixtures', 'cross-stock-stripe.ts.fixture'), path.join(dir, 'convex', 'cross_stock_stripe.ts'));
    const payments = path.join(dir, 'convex', 'rentalSwapPayments.ts');
    const source = fs.readFileSync(payments, 'utf8');
    if (!source.includes('import Stripe from "stripe";')) throw Error('The synthetic payment adapter no longer matches the real payment handler.');
    fs.writeFileSync(payments, source.replace('import Stripe from "stripe";', 'import Stripe from "./cross_stock_stripe";'));
    fs.writeFileSync(path.join(dir, 'convex', 'lib', 'rentalSwapAuthority.ts'), 'export function swapAuthorityAvailable() { return true; }\nexport function assertSwapAuthorityAvailable() {}\n');
  }
  fs.rmSync(path.join(dir, 'convex', 'crons.ts'), { force: true });
  const env = { PATH: process.env.PATH, HOME: process.env.HOME, CONVEX_AGENT_MODE: 'anonymous', XDG_CONFIG_HOME: path.join(dir, 'config') };
  const cli = path.join(source, 'node_modules/.bin/convex');
  const child = spawn(cli, ['dev', '--configure', 'new', '--project', `cross-stock-${name}`, '--dev-deployment', 'local', '--typecheck', 'disable', '--codegen', 'disable', '--tail-logs', 'disable'], { cwd: dir, env, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
  children.push(child);
  let output = '';
  child.stdout.on('data', data => { output += data; }); child.stderr.on('data', data => { output += data; });
  for (let attempt = 0; attempt < 180 && !output.includes('Convex functions ready!') && !output.includes('✘ [ERROR]') && child.exitCode === null && child.signalCode === null; attempt++) await sleep(1000);
  const match = output.match(/http:\/\/127\.0\.0\.1:(\d+)/);
  const localConfig = path.join(dir, '.convex', 'local', 'default', 'config.json');
  if (!output.includes('Convex functions ready!') || !(output.includes('[Local]') || output.includes('Configured a local deployment')) || !fs.existsSync(localConfig) || !match) throw Error(`${name} isolated backend failed: ${output.slice(-1500)}`);
  return { dir, cli, env, client: new ConvexHttpClient(match[0]), site: `http://127.0.0.1:${Number(match[1]) + 1}/dbcinema/shared-stock` };
}

